/* Token Radar — dashboard styles. Original dark-slate design: dense but readable
   table, color-coded movement, stat tiles, and a right-hand detail drawer. Plain
   CSS, no frameworks, no network. */
:root {
  --bg: #0f1420;
  --panel: #171e2e;
  --panel2: #1d2639;
  --line: #263046;
  --text: #e6ecf5;
  --muted: #8b98ad;
  --accent: #38e08b;
  --accent-dim: #1f9e63;
  --up: #38e08b;
  --down: #ff6b6b;
  --gold: #ffd166;
  --radius: 10px;
  --shadow: 0 8px 30px rgba(0, 0, 0, .35);
}
* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: radial-gradient(1200px 600px at 80% -10%, #1b2842 0%, var(--bg) 55%);
  color: var(--text);
  font: 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}
.skip { position: absolute; left: -999px; top: 0; }
.skip:focus { left: 8px; top: 8px; background: var(--panel); padding: 8px 12px; border-radius: 6px; z-index: 50; }

.shell { max-width: 1200px; margin: 0 auto; padding: 24px 20px 48px; }

.head { display: flex; align-items: center; gap: 10px; margin-bottom: 18px; }
.brand-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 10px var(--accent); }
.brand { font-weight: 700; letter-spacing: .2px; }
.head .meta { margin-left: auto; color: var(--muted); font-size: 12.5px; }

.title-row { display: flex; gap: 20px; align-items: flex-start; flex-wrap: wrap; margin-bottom: 18px; }
.title-block { flex: 1 1 420px; }
h1 { font-size: 26px; line-height: 1.2; margin: 0 0 8px; }
.sub { color: var(--muted); font-size: 13.5px; margin: 4px 0; }
.stat-grid { display: grid; grid-template-columns: repeat(2, minmax(140px, 1fr)); gap: 10px; flex: 1 1 260px; }
.stat { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 10px 14px; }
.stat b { display: block; font-size: 20px; }
.stat span { color: var(--muted); font-size: 12px; }

.controls { display: flex; gap: 10px; flex-wrap: wrap; align-items: center; margin-bottom: 14px; }
.controls input[type=search] {
  flex: 1 1 220px; background: var(--panel); color: var(--text);
  border: 1px solid var(--line); border-radius: 8px; padding: 9px 12px; font-size: 14px;
}
.controls select {
  background: var(--panel); color: var(--text); border: 1px solid var(--line);
  border-radius: 8px; padding: 9px 10px; font-size: 14px; max-width: 230px;
}
.tabs { display: inline-flex; background: var(--panel); border: 1px solid var(--line); border-radius: 8px; overflow: hidden; }
.tabs button {
  background: transparent; border: 0; color: var(--muted); font: 600 13.5px/1 system-ui, sans-serif;
  padding: 9px 16px; cursor: pointer;
}
.tabs button[aria-pressed=true] { background: var(--panel2); color: var(--text); }
.count { margin-left: auto; color: var(--muted); font-size: 13px; }

.table-wrap { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); overflow: auto; max-height: 560px; }
table { border-collapse: collapse; width: 100%; font-size: 13.5px; }
caption { text-align: left; padding: 12px 16px; color: var(--muted); font-size: 12.5px; }
th, td { text-align: left; padding: 10px 14px; border-bottom: 1px solid var(--line); white-space: nowrap; }
thead th { position: sticky; top: 0; background: var(--panel2); color: var(--muted); font-weight: 600; z-index: 2; cursor: pointer; user-select: none; }
tbody tr { cursor: pointer; }
tbody tr:hover { background: #1b2437; }
tbody tr[data-selected=true] { background: #20304a; }
.arrow { color: var(--accent); }
.num { font-variant-numeric: tabular-nums; }
.pos { color: var(--up); } .neg { color: var(--down); }
.rk { color: var(--muted); }
.bar { display: inline-block; width: 70px; height: 7px; background: #26364a; border-radius: 4px; margin-right: 8px; vertical-align: middle; }
.bar i { display: block; height: 100%; background: var(--accent); border-radius: 4px; }
.chip { display: inline-block; padding: 2px 8px; border-radius: 20px; font-size: 11.5px; background: var(--panel2); color: var(--muted); }
.chip.none { color: var(--gold); background: #3a2f16; }

.panel { background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); padding: 16px 18px; margin-top: 18px; }
.panel h2 { font-size: 16px; margin: 0 0 6px; }
.formula { background: var(--panel2); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; font-family: ui-monospace, "SFMono-Regular", Menlo, monospace; font-size: 12.5px; overflow-x: auto; margin: 10px 0; }
.empty { text-align: center; padding: 40px 20px; color: var(--muted); }

dialog.detail { border: 0; border-radius: var(--radius); background: var(--panel); color: var(--text); padding: 0; width: min(520px, 92vw); box-shadow: var(--shadow); }
dialog.detail::backdrop { background: rgba(4, 7, 14, .6); }
.detail-head { display: flex; align-items: flex-start; gap: 12px; padding: 18px 20px 12px; border-bottom: 1px solid var(--line); }
.detail-head h2 { margin: 2px 0 4px; font-size: 19px; }
.brand-name { color: var(--accent-dim); font-size: 12px; font-weight: 600; }
button.close { margin-left: auto; background: var(--panel2); border: 1px solid var(--line); color: var(--muted); border-radius: 8px; padding: 6px 12px; cursor: pointer; font-size: 13px; }
.detail-section { padding: 16px 20px; }
.detail-section h3 { font-size: 14px; margin: 0 0 10px; color: var(--muted); text-transform: uppercase; letter-spacing: .4px; }
.equation { display: grid; grid-template-columns: 1fr auto; gap: 8px 14px; margin-bottom: 12px; }
.equation > div { display: flex; justify-content: space-between; gap: 10px; border-bottom: 1px solid var(--line); padding-bottom: 6px; }
.equation span { color: var(--muted); }
.equation .num { font-weight: 600; }
.equation .num.final { color: var(--accent); font-size: 18px; }
.farmsteps { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 10px; }
.farmsteps li { background: var(--panel2); border: 1px solid var(--line); border-radius: 8px; padding: 10px 12px; font-size: 13px; }
.farmsteps code { display: block; color: var(--muted); font-size: 12px; margin-top: 4px; font-family: ui-monospace, Menlo, monospace; }

@media (max-width: 760px) {
  .title-row { flex-direction: column; }
  .stat-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: 0.01ms !important; scroll-behavior: auto !important; }
}
